Okay. I run a demo with following code:
#include <cstdio>
#include <cstdint>
#include <utility>
#include <cinttypes>
#include <unistd.h>

std::pair<uint64_t, uint64_t> GetCpuStatsImpl() {
  uint64_t busy = 0, total = 0;
  FILE* fp;
  fp = fopen("/proc/stat", "r");
  uint64_t user, nice, system, idle;
  if (fscanf(fp, "cpu %" PRIu64 " %" PRIu64 " %" PRIu64 " %" PRIu64, &user,
             &nice, &system, &idle) != 4) {
    // Something bad happened with the information, so assume it's all invalid
    user = nice = system = idle = 0;
  }
  fclose(fp);
  busy = user + nice + system;
  total = busy + idle;
  return std::make_pair(busy, total);
}

int main() {
  const size_t kRuns = 100;
  auto prev = GetCpuStatsImpl();
  for (size_t i = 0; i < kRuns; ++i) {
    // sleep(1);
    auto cur = GetCpuStatsImpl();
    if (prev.first > cur.first) {
        printf("got");
        printf("%d,%d", prev.first, cur.first);
    }
    prev = cur;
  }
  return 0;
}
And I found that this problem has nothing to do with grpc indeed. It looks more like a 6.1 kernel problem, because it occured occasionally (about once thousands of times)  not only on ARM but also on x86.
